<template><EnterpriseAuthShell><div class="auth-panel"><span class="eyebrow">重置密码</span><h2>设置新的登录密码</h2><p class="subtitle">请设置新的密码以恢复访问企业工作区。完成后可使用新密码重新登录。</p><el-alert v-if="!token" title="重置链接缺少令牌" type="error" :closable="false" class="mb"/><el-alert v-if="error" :title="error" type="error" :closable="false" class="mb"/><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><el-form-item label="新密码" prop="password"><el-input v-model="form.password" type="password" show-password size="large" :prefix-icon="Lock" /></el-form-item><el-form-item label="确认新密码" prop="confirm"><el-input v-model="form.confirm" type="password" show-password size="large" :prefix-icon="Lock" /></el-form-item><div class="neutral-note"><strong>忘记密码申请的中性反馈</strong><p>申请后统一提示"如账户符合重置条件，将发送后续指引"，不披露邮箱、企业或资格信息。</p></div><el-button type="primary" size="large" :disabled="!token" :loading="loading" @click="submit">确认重置并登录</el-button><div class="auth-links"><RouterLink to="/enterprise/login">返回企业登录</RouterLink></div></el-form></div></EnterpriseAuthShell></template>
<script setup lang="ts">import { reactive,ref } from 'vue';import { RouterLink,useRoute,useRouter } from 'vue-router';import type { FormInstance,FormRules } from 'element-plus';import { ElMessage } from 'element-plus';import { Lock } from '@element-plus/icons-vue';import EnterpriseAuthShell from '@/components/enterprise/EnterpriseAuthShell.vue';import { enterpriseAPI } from '@/api/enterprise';import { validatePassword } from '@/features/enterprise/validation';const route=useRoute(),router=useRouter(),token=typeof route.query.token==='string'?route.query.token:'',formRef=ref<FormInstance>(),loading=ref(false),error=ref(''),form=reactive({password:'',confirm:''});const rules:FormRules={password:[{validator:(_r,_v,cb)=>{const message=validatePassword(form.password);message?cb(new Error(message)):cb()},trigger:'blur'}],confirm:[{validator:(_r,_v,cb)=>form.confirm===form.password?cb():cb(new Error('两次输入的密码不一致')),trigger:'blur'}]};async function submit(){if(!await formRef.value?.validate().catch(()=>false))return;loading.value=true;error.value='';try{await enterpriseAPI.resetPassword(token,form.password);ElMessage.success('密码已重置');await router.replace('/enterprise/login')}catch(e){const candidate=e as{reason?:string;message?:string};if(candidate.reason==='PASSWORD_RESET_INVALID'){await router.replace('/enterprise/session-states?state=reset-link-invalid');return}error.value=candidate.message||'重置失败'}finally{loading.value=false}}</script><style scoped>.mb{margin-bottom:20px}.eyebrow{display:block;margin-bottom:6px;color:#2563eb;font-size:12px;font-weight:700}.neutral-note{margin-bottom:20px;padding:12px 14px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px}.neutral-note strong{display:block;margin-bottom:4px;font-size:13px}.neutral-note p{margin:0;color:#64748b;font-size:12px;line-height:1.6}</style>
